.dietary-tags{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  align-items:center;
  justify-content:center; /* center horizontally */
  text-align:center;
  width:100%;
  font-family:Arial, sans-serif;
}

.tag{
  display:flex;
  align-items:center;
  gap:8px;
  padding:6px 14px 6px 6px;
  border-radius:50px;
  font-size:14px;
  font-weight:600;
  background:#f5f5f5;
  border:2px solid transparent;
  white-space:nowrap;
}

.tag .icon{
  width:24px;
  height:24px;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:13px;
  color:#fff;
  font-weight:bold;
}

/* VEGAN (Green) */
.vegan{ border-color:#2e7d32; }
.vegan .icon{ background:#2e7d32; }

/* GLUTEN FREE (Blue) */
.gluten{ border-color:#2f4fa3; }
.gluten .icon{ background:#2f4fa3; }

/* JAIN (Orange) */
.jain{ border-color:#f39c12; }
.jain .icon{ background:#f39c12; }

/* CONTAIN NUTS (Red) */
.nuts{ border-color:#e53935; }
.nuts .icon{ background:#e53935; }

/* ASK FOR VEGAN (Grey) */
.ask{ border-color:#6e6e6e; }
.ask .icon{ background:#6e6e6e; }

/* Mobile Responsive */
@media(max-width:480px){
  .dietary-tags{
    justify-content:center;
  }
  .tag{
    font-size:12px;
    padding:5px 12px 5px 5px;
  }
  .tag .icon{
    width:20px;
    height:20px;
    font-size:11px;
  }
}
</style>

