  <div class="tag gluten">
    <span class="icon">G</span>
    <span>GLUTEN FREE</span>
  </div>

  <div class="tag jain">
    <span class="icon">J</span>
    <span>JAIN</span>
  </div>

  <div class="tag vegan">
    <span class="icon">V</span>
    <span>VEGAN</span>
  </div>

  <div class="tag nuts">
    <span class="icon">N</span>
    <span>CONTAIN NUTS</span>
  </div>

  <div class="tag ask">
    <span class="icon">?</span>
    <span>Ask for VEGAN</span>
  </div>

